// parallax mountains + grounded trees (two rows, bases at y=0, second row darker)
for(let i=0;i<30;i++){const h=8+Math.random()*14;const m=new THREE.Mesh(new THREE.ConeGeometry(6+Math.random()*6,h,5),M(i%2?0x2e6b34:0x3a7d44,1));m.position.set(i*14-40, h/2-3, -50-Math.random()*20);scene.add(m);}
function tree(x,z,s=1,dark=false){const t=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.25*s,.35*s,2.4*s,6),M(0x6b4a2b));trunk.position.y=1.2*s;trunk.castShadow=true;t.add(trunk);for(let k=0;k<2;k++){const top=new THREE.Mesh(new THREE.ConeGeometry((1.7-k*0.4)*s,2.2*s,7),M(dark?0x175423:0x1f7a2e,1));top.position.y=(2.8+k*1.4)*s;top.castShadow=true;t.add(top);}t.position.set(x,0,z);scene.add(t);}
for(let i=0;i<40;i++){tree(i*6.5-50+Math.random()*2,-11-Math.random()*4,0.9+Math.random()*0.5,false);}
for(let i=0;i<24;i++){tree(i*11-55,-20-Math.random()*6,1.3+Math.random()*0.7,true);}

