pg.add(legL,legR,torso,head,band,armR,gunM);pg.traverse(o=>{o.castShadow=true});scene.add(pg);
// leg pivots at hip (rotate around top, not center)
for(const l of [legL,legR]){l.geometry.translate(0,-0.4,0);l.position.y=0.8;}
// Sketchfab GLB hero + runner skins (Kolos Studios low poly soldier, CC Attribution) — progressive enhancement over boxes
let heroGLB=null,heroMixer=null;const runnerSkins=[];
async function loadSoldiers(){try{
  const {GLTFLoader}=await import('three/addons/loaders/GLTFLoader.js');
  const gltf=await new GLTFLoader().loadAsync('./models/soldier.glb');
  const src=gltf.scene;
  // hero: fit ~1.9m, standing clip
  heroGLB=src.clone();heroGLB.scale.setScalar(1.05);heroGLB.traverse(o=>{if(o.isMesh){o.castShadow=true;}});
  heroMixer=new THREE.AnimationMixer(heroGLB);if(gltf.animations.length){heroMixer.clipAction(gltf.animations[0]).play();}
  pg.visible=false;scene.add(heroGLB);
  // runners: red-tinted clones
  for(const e of enemies){if(e.kind!=='runner')continue;
    const c=src.clone();c.scale.setScalar(1.0);
    c.traverse(o=>{if(o.isMesh){o.castShadow=true;o.material=o.material.clone();if(o.material.color)o.material.color.multiply(new THREE.Color(0xff6666));}});
    c.position.set(e.x,0,0);scene.add(c);e.g.visible=false;e.skin=c;
    const mx=new THREE.AnimationMixer(c);if(gltf.animations.length)mx.clipAction(gltf.animations[0]).play();e.mixer=mx;
  }
  toast('HD TROOPS LOADED');
}catch(err){console.warn('soldier GLB fallback to boxes',err);}}
loadSoldiers();

